-- SEO Mission 2, part B point 8: the Team quiz "BTS ARMY level test" (/q/bts-army-level-test), as a DRAFT.
-- Generated by apps/quiz/scripts/build-team-quiz-sql.mjs from
-- apps/quiz/src/data/team-quizzes/bts-army-level-test.json (questions, answers, fun facts and the sources
-- each answer was checked against). Do not edit by hand: edit the JSON and re-run the script.
--
-- What it does, in one transaction:
--   1. refuses to run if the slug already exists or the Team profile is missing;
--   2. inserts the quiz with status 'draft', owned by the KpopQuizz Team profile
--      (00000000-0000-0000-0000-000000000001), in the bts group. A draft is not public: /q/bts-army-level-test
--      answers 404, and it is in no list, sitemap or count of published quizzes;
--   3. the insert trigger handle_new_quiz() adds 1 to groups.quiz_count and to the Team's
--      profiles.total_quizzes_created (as for every quiz) and writes a 'quiz_created' activity
--      event; that event is deleted here, so the feed never points at an unpublished quiz.
--      No alert is sent: the alert triggers fire only on 'published'.
--
-- The level result: settings.result_levels (read by apps/quiz/src/lib/quiz/result-levels.ts).
-- The results screen names the level reached; "You beat N% of players" shows only from 200
-- finished attempts. A quiz without result_levels is unchanged.
--
-- Run: Supabase SQL editor, the whole file. Rollback: seo-m2-bts-army-level-test-rollback.sql.
--
-- PUBLISH, only with the owner's go, after reading the draft (this fires the group's
-- "new quiz" alerts once, like any publish):
--   update public.quizzes set status = 'published', updated_at = now()
--   where slug = 'bts-army-level-test' and status = 'draft';

begin;

do $guard$
begin
  if exists (select 1 from public.quizzes where slug = 'bts-army-level-test') then
    raise exception 'quiz % already exists', 'bts-army-level-test';
  end if;
  if not exists (select 1 from public.profiles where id = '00000000-0000-0000-0000-000000000001'::uuid) then
    raise exception 'Team profile % is missing', '00000000-0000-0000-0000-000000000001';
  end if;
  if not exists (select 1 from public.groups where slug = 'bts') then
    raise exception 'group % is missing', 'bts';
  end if;
end
$guard$;

insert into public.quizzes (creator_id, group_id, title, slug, quiz_type, questions, settings, difficulty, status, question_count, language)
select
  '00000000-0000-0000-0000-000000000001'::uuid,
  g.id,
  'BTS ARMY level test',
  'bts-army-level-test',
  'multiple_choice',
  $json$[
  {
    "question": "What does the name BTS stand for in Korean?",
    "options": [
      "Bangtan Sonyeondan",
      "Bangtan Sonamu",
      "Boys To Stars",
      "Beyond The Stage"
    ],
    "correct": 0,
    "fun_fact": "Bangtan Sonyeondan means Bulletproof Boy Scouts. Since July 2017 the letters also stand for Beyond the Scene. Source: Wikipedia."
  },
  {
    "question": "What is the official name of the BTS fandom?",
    "options": [
      "BLINK",
      "ARMY",
      "CARAT",
      "ONCE"
    ],
    "correct": 1,
    "fun_fact": "BTS picked the name A.R.M.Y. for their fan club at their first fan meeting in Seoul, in 2014. Source: Wikipedia."
  },
  {
    "question": "In which year did BTS debut?",
    "options": [
      "2011",
      "2012",
      "2013",
      "2015"
    ],
    "correct": 2,
    "fun_fact": "BTS made their stage debut on 13 June 2013 on M Countdown, performing No More Dream. Source: Wikipedia."
  },
  {
    "question": "Which member is the leader of BTS?",
    "options": [
      "Jin",
      "SUGA",
      "RM",
      "Jung Kook"
    ],
    "correct": 2,
    "fun_fact": "RM is a rapper, songwriter and producer. Big Hit first planned a hip hop group around him before BTS became an idol group. Source: Wikipedia."
  },
  {
    "question": "Which song was the first English-language single of BTS, released in August 2020?",
    "options": [
      "Butter",
      "Dynamite",
      "Permission to Dance",
      "Life Goes On"
    ],
    "correct": 1,
    "fun_fact": "Dynamite debuted at number one on the Billboard Hot 100, the first chart-topper for BTS and for an all-South Korean act. Source: Billboard."
  },
  {
    "question": "What was the title of the debut single album of BTS?",
    "options": [
      "O!RUL8,2?",
      "Skool Luv Affair",
      "2 Cool 4 Skool",
      "Dark & Wild"
    ],
    "correct": 2,
    "fun_fact": "2 Cool 4 Skool came out in June 2013 with the lead single No More Dream. It opened their school trilogy. Source: Wikipedia."
  },
  {
    "question": "Which BTS album was the first to sell one million copies in South Korea?",
    "options": [
      "Dark & Wild",
      "Wings",
      "Love Yourself: Her",
      "The Most Beautiful Moment in Life: Young Forever"
    ],
    "correct": 1,
    "fun_fact": "Wings (2016) was inspired by the Hermann Hesse novel Demian. Source: Wikipedia."
  },
  {
    "question": "Which BTS album was the first K-pop album to top the US Billboard 200?",
    "options": [
      "Wings",
      "Love Yourself: Tear",
      "Map of the Soul: Persona",
      "Be"
    ],
    "correct": 1,
    "fun_fact": "Love Yourself: Tear debuted at number one on the Billboard 200 in 2018, the first number-one album of BTS in the US. Source: Wikipedia."
  },
  {
    "question": "Which American singer is featured on the BTS single Boy with Luv?",
    "options": [
      "Charli XCX",
      "Lauv",
      "Halsey",
      "Zara Larsson"
    ],
    "correct": 2,
    "fun_fact": "Boy with Luv led the 2019 EP Map of the Soul: Persona. BTS then became the first K-pop act to perform on Saturday Night Live. Source: Wikipedia."
  },
  {
    "question": "Which band released the 2021 single My Universe with BTS?",
    "options": [
      "Imagine Dragons",
      "Coldplay",
      "Maroon 5",
      "The Chainsmokers"
    ],
    "correct": 1,
