  },
  {
    "question": "Which song was the first entry of BTS on the Billboard Hot 100?",
    "options": [
      "Fake Love",
      "Mic Drop",
      "Spring Day",
      "DNA"
    ],
    "correct": 3,
    "fun_fact": "DNA entered the Hot 100 at number 85 in 2017, making BTS the first K-pop boy band to reach that chart. Source: Wikipedia."
  },
  {
    "question": "Which BTS song was the first song performed mainly in Korean to top the Billboard Hot 100?",
    "options": [
      "Life Goes On",
      "Fake Love",
      "Spring Day",
      "Black Swan"
    ],
    "correct": 0,
    "fun_fact": "Life Goes On led the 2020 album Be and was the third US number-one single of BTS in three months. Source: Wikipedia."
