    ],
    "correct": 1,
    "fun_fact": "Arirang came out on 20 March 2026 with the lead single Swim and spent two weeks at number one on the Billboard 200. Source: Wikipedia."
  }
]$json$::jsonb,
  $json${
  "timer": true,
  "timer_seconds": 20,
  "shuffle": false,
  "show_answers": true,
  "creator_note": "Fifteen sourced questions that get harder as you go, from the basics every fan knows to chart records. Your result is an ARMY level, not just a score.",
  "result_levels": [
    {
      "min": 0,
      "name": "Trainee ARMY",
      "blurb": "You know the basics. Play the easy BTS quizzes on the hub and come back for a rematch."
    },
    {
      "min": 40,
      "name": "Rookie ARMY",
      "blurb": "A solid start. The albums and the chart history are where your next points are."
    },
    {
      "min": 60,
      "name": "Dedicated ARMY",
      "blurb": "You know the discography well. A few records and collaborations stand between you and the top."
    },
    {
      "min": 80,
      "name": "Veteran ARMY",
      "blurb": "Only the hardest chart and stage facts got past you. Very few fans score this high."
    },
    {
      "min": 100,
      "name": "Legendary ARMY",
      "blurb": "A perfect score. Every question, from the debut to the comeback, answered right."
    }
  ]
}$json$::jsonb,
  'medium',
  'draft',
  15,
  'en'
from public.groups g
where g.slug = 'bts';

-- The 'quiz_created' event the insert trigger just wrote (same transaction, so now() is the
-- same instant as its created_at default).
delete from public.activity_events
where event_type = 'quiz_created'
  and user_id = '00000000-0000-0000-0000-000000000001'::uuid
  and payload ->> 'title' = 'BTS ARMY level test'
  and created_at = now();

commit;
